#[verifier::spec]
fn is_ascii_digit(c: char) -> bool {
    c >= '0' && c <= '9'
}

#[verifier::spec]
fn digit_value(c: char) -> nat {
    // Precondition: is_ascii_digit(c)
    (c as u8 - b'0') as nat
}

#[verifier::spec]
fn good_count(d: nat) -> nat {
    // Precondition: d <= 9
    match d {
        0 => 2,
        1 => 7,
        2 => 2,
        3 => 3,
        4 => 3,
        5 => 4,
        6 => 2,
        7 => 5,
        8 => 1,
        9 => 2,
        _ => 0, // unreachable if caller respects precondition
    }
}

#[verifier::spec]
fn char_of_digit(d: nat) -> char {
    // Precondition: d <= 9
    (((d as u8) + b'0') as char)
}

// Recursively build the decimal representation of a natural number (≤ 49 here)
#[verifier::spec]
fn decimal_chars(n: nat) -> Seq<char> {
    if n < 10 {
        Seq::singleton(char_of_digit(n))
    } else {
        let rest = decimal_chars(n / 10);
        rest + Seq::singleton(char_of_digit(n % 10))
    }
}

